import SwiftUI

/// Images generated by AI, as a grid of variations: placeholders while they
/// generate, previews with progress while they refine, then each image with
/// a required alt text field and "Use image" and "More like this" actions.
///
/// ```swift
/// MonarchAiImageGeneration(
///     images: $images,
///     status: .done,
///     selection: $chosen,
///     onVariations: { id in generateMore(like: id) }
/// )
/// ```
///
/// The images are a binding, so the alt text fields write `alt` back.
/// "Use image" appears when you pass `selection`, "More like this" when you
/// pass `onVariations`. Only `http`, `https` and `file` addresses are loaded;
/// any other address shows "Preview unavailable".
///
/// Accessibility: a container named "AI generated images". The status line
/// is text; the progress bar is hidden because the line carries the
/// percentage. Completion is announced once. Each image is read by its alt
/// text, or "Generated image n" while that is empty; each alt field has its
/// own label and error. The action buttons are named with the image's
/// position, and "Use image" has the selected trait on the chosen image,
/// which also has a ring and a "Selected" mark.
public struct MonarchAiImageGeneration: View {
    @Binding private var images: [MonarchAiGeneratedImage]
    private let status: MonarchAiImageGenerationStatus
    private let progress: Double?
    private let selection: Binding<String?>?
    private let error: String?
    private let labels: MonarchAiImageGenerationLabels
    private let onVariations: (@MainActor (String) -> Void)?
    private let onRetry: (@MainActor () -> Void)?

    @Environment(\.monarchTheme) private var theme
    @Environment(\.locale) private var locale
    @ScaledMetric(relativeTo: .body) private var minimumColumnWidth = MonarchAiImageGenerationTokens.minimumColumnWidth

    /// An image generation grid.
    ///
    /// - Parameters:
    ///   - images: The images, or their slots while generating. Alt text edits are written back.
    ///   - status: Where the generation is.
    ///   - progress: Overall progress from 0 to 1, shown while generating.
    ///   - selection: The id of the chosen image. Passing it adds "Use image" to each finished image.
    ///   - error: Replaces the built-in error message.
    ///   - labels: Replaces the built-in strings.
    ///   - onVariations: Adds "More like this" to each finished image; gets its id.
    ///   - onRetry: Adds a retry button in the error state.
    public init(
        images: Binding<[MonarchAiGeneratedImage]>,
        status: MonarchAiImageGenerationStatus,
        progress: Double? = nil,
        selection: Binding<String?>? = nil,
        error: String? = nil,
        labels: MonarchAiImageGenerationLabels = MonarchAiImageGenerationLabels(),
        onVariations: (@MainActor (String) -> Void)? = nil,
        onRetry: (@MainActor () -> Void)? = nil
    ) {
        _images = images
        self.status = status
        self.progress = progress
        self.selection = selection
        self.error = error
        self.labels = labels
        self.onVariations = onVariations
        self.onRetry = onRetry
    }

    private typealias Tokens = MonarchAiImageGenerationTokens

    /// The content of the view.
    public var body: some View {
        VStack(alignment: .leading, spacing: Tokens.sectionSpacing) {
            if let text = Tokens.statusText(
                status: status,
                progress: progress,
                count: images.count,
                locale: locale,
                labels: labels
            ) {
                Text(text)
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
            } else if let onRetry {
                MonarchInlineErrorRetry(
                    error ?? labels.error,
                    variant: .banner,
                    retryLabel: labels.retry,
                    onRetry: onRetry
                )
            } else {
                MonarchInlineNotice(error ?? labels.error, tone: .danger)
            }
            if Tokens.isGenerating(status), let value = Tokens.clamped(progress) {
                ProgressView(value: value)
                    .progressViewStyle(.monarchLinear)
                    .accessibilityHidden(true)
            }
            if !images.isEmpty {
                LazyVGrid(
                    columns: [
                        GridItem(.adaptive(minimum: minimumColumnWidth), spacing: Tokens.gridSpacing, alignment: .top)
                    ],
                    alignment: .leading,
                    spacing: Tokens.gridSpacing
                ) {
                    ForEach(Array(images.enumerated()), id: \.element.id) { index, image in
                        item(image, index: index)
                    }
                }
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .accessibilityElement(children: .contain)
        .accessibilityLabel(labels.label)
        .onChange(of: status) { old, new in
            if Tokens.announcesCompletion(from: old, to: new) {
                AccessibilityNotification.Announcement(labels.announceDone(images.count)).post()
            }
        }
    }

    private func item(_ image: MonarchAiGeneratedImage, index: Int) -> some View {
        let position = index + 1
        let isSelected = selection?.wrappedValue == image.id
        let isInvalid = Tokens.isAltInvalid(image.alt, status: status)
        return VStack(alignment: .leading, spacing: Tokens.itemSpacing) {
            MonarchAiImageGenerationSlot(
                image: image,
                slot: Tokens.slot(for: image, status: status),
                isSelected: isSelected,
                name: Tokens.spokenName(alt: image.alt, position: position, labels: labels),
                labels: labels
            )
            MonarchTextField(
                labels.altLabel(position),
                text: altBinding(index: index, fallback: image.alt),
                error: isInvalid ? labels.altRequired : nil,
                isRequired: true
            )
            .disabled(status == .pending)
            if Tokens.showsActions(
                for: image,
                status: status,
                canSelect: selection != nil,
                canVary: onVariations != nil
            ) {
                MonarchFlowLayout(spacing: Tokens.itemSpacing) {
                    if let selection {
                        Button(labels.select) { selection.wrappedValue = image.id }
                            .buttonStyle(.monarch(isSelected ? .primary : .secondary, size: .sm))
                            .accessibilityLabel(labels.selectName(position))
                            .accessibilityAddTraits(isSelected ? .isSelected : [])
                    }
                    if let onVariations {
                        Button(labels.variations) { onVariations(image.id) }
                            .buttonStyle(.monarch(.ghost, size: .sm))
                            .accessibilityLabel(labels.variationsName(position))
                    }
                }
            }
        }
    }

    private func altBinding(index: Int, fallback: String) -> Binding<String> {
        Binding(
            get: { images.indices.contains(index) ? images[index].alt : fallback },
            set: { value in
                if images.indices.contains(index) {
                    images[index].alt = value
                }
            }
        )
    }
}

/// The square frame of one image: the image, a pulsing placeholder or
/// "Preview unavailable", with the ring and mark of the chosen image.
private struct MonarchAiImageGenerationSlot: View {
    let image: MonarchAiGeneratedImage
    let slot: MonarchAiImageGenerationTokens.Slot
    let isSelected: Bool
    let name: String
    let labels: MonarchAiImageGenerationLabels

    @Environment(\.monarchTheme) private var theme
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    private typealias Tokens = MonarchAiImageGenerationTokens

    var body: some View {
        Rectangle()
            .fill(theme.colors[role: Tokens.slot])
            .aspectRatio(1, contentMode: .fit)
            .overlay { content }
            .clipShape(MonarchShapes.control)
            .overlay(
                MonarchShapes.control.strokeBorder(
                    theme.colors[role: isSelected ? \.textDefault : \.borderSubtle],
                    lineWidth: isSelected ? Tokens.selectedRingWidth : MonarchShapes.borderWidth
                )
            )
            .overlay(alignment: .topLeading) {
                if isSelected {
                    Text(labels.selected)
                        .monarchTextStyle(.caption)
                        .padding(.horizontal, Tokens.markPadding)
                        .padding(.vertical, Tokens.markInset)
                        .monarchSurface(
                            MonarchSurfaceAppearance(background: \.bgInverse, foreground: \.textInverse, border: nil),
                            in: Capsule()
                        )
                        .padding(Tokens.markPadding)
                        .accessibilityHidden(true)
                }
            }
    }

    @ViewBuilder private var content: some View {
        switch slot {
        case .image, .refining:
            picture
                .blur(radius: slot == .refining ? Tokens.refiningBlur : 0)
                .accessibilityElement(children: .ignore)
                .accessibilityLabel(name)
                .accessibilityAddTraits(.isImage)
        case .placeholder:
            if reduceMotion {
                Color.clear
            } else {
                TimelineView(.animation) { context in
                    Rectangle()
                        .fill(theme.colors[role: Tokens.shimmer])
                        .opacity(MonarchPulse.value(at: context.date.timeIntervalSinceReferenceDate))
                }
                .accessibilityHidden(true)
            }
        case .unavailable:
            Text(labels.unavailable)
                .monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
                .multilineTextAlignment(.center)
                .padding(Tokens.markPadding)
        }
    }

    @ViewBuilder private var picture: some View {
        if let loaded = image.image {
            MonarchRemoteImage(image: loaded) { Color.clear }
        } else {
            MonarchRemoteImage(url: image.url) { Color.clear }
        }
    }
}

